// Validar y procesar entrada del usuario
const input = $input.first().json;

// Validaciones
if (!input.question || input.question.trim().length === 0) {
  return [{ json: { error: 'Question is required' } }];
}

if (input.question.length > 2000) {
  return [{ json: { error: 'Question too long (max 2000 characters)' } }];
}

// Procesar entrada
const processedInput = {
  question: input.question.trim(),
  user_id: input.user_id || 'anonymous',
  session_id: input.session_id || `session_${Date.now()}`,
  conversation_id: input.conversation_id || null,
  timestamp: new Date().toISOString(),
  metadata: {
    user_agent: input.user_agent || 'unknown',
    ip_address: input.ip_address || 'unknown'
  }
};

return [{ json: processedInput }];

// Construir contexto para Claude
const searchResults = $input.first().json.result || [];
const userQuestion = $('Validate Input').first().json.question;

if (searchResults.length === 0) {
  return [{ json: {
    prompt: `No se encontraron documentos relevantes para responder la pregunta: "${userQuestion}". Por favor, indica que no tienes información suficiente para responder esta pregunta específica.`,
    context: [],
    has_context: false
  }}];
}

// Construir contexto de documentos
const contextText = searchResults.map((item, index) => 
  `DOCUMENTO ${index + 1}:
Archivo: ${item.payload.filename}
Contenido: ${item.payload.text}
Relevancia: ${item.score.toFixed(3)}
`
).join('\n---\n\n');

// Construir prompt optimizado para Claude
const prompt = `Eres un asistente especializado en análisis de documentos PDF. Tu tarea es responder preguntas basándote únicamente en el contexto proporcionado.

CONTEXTO DE DOCUMENTOS:
${contextText}

PREGUNTA DEL USUARIO:
${userQuestion}

INSTRUCCIONES:
1. Analiza cuidadosamente el contexto proporcionado
2. Responde de manera precisa y detallada basándote ÚNICAMENTE en la información del contexto
3. Cita las fuentes específicas cuando sea relevante (menciona el nombre del archivo)
4. Si la información no está disponible en el contexto, indícalo claramente
5. Para preguntas complejas, estructura tu respuesta en secciones
6. Responde en español
7. Sé conciso pero completo

RESPUESTA:`;

return [{ json: {
  prompt: prompt,
  context: searchResults,
  has_context: true,
  context_count: searchResults.length
}}];

// Procesar respuesta de Claude
const claudeResponse = $input.first().json;
const userInput = $('Validate Input').first().json;
const context = $('Build Context').first().json;

// Extraer respuesta
let responseText = '';
if (claudeResponse.content && claudeResponse.content[0] && claudeResponse.content[0].text) {
  responseText = claudeResponse.content[0].text;
} else {
  responseText = 'Lo siento, no pude procesar tu pregunta en este momento.';
}

// Preparar datos para guardar en historial
const conversationData = {
  user_message: {
    conversation_id: userInput.conversation_id,
    user_id: userInput.user_id,
    session_id: userInput.session_id,
    role: 'user',
    content: userInput.question,
    created_at: userInput.timestamp,
    metadata: userInput.metadata
  },
  assistant_message: {
    role: 'assistant',
    content: responseText,
    created_at: new Date().toISOString(),
    tokens_used: claudeResponse.usage?.total_tokens || 0,
    model_used: 'claude-3-sonnet',
    metadata: {
      context_documents: context.context?.length || 0,
      has_context: context.has_context,
      processing_time: Date.now() - new Date(userInput.timestamp).getTime()
    }
  },
  referenced_documents: context.context?.map(doc => ({
    filename: doc.payload.filename,
    relevance_score: doc.score,
    chunk_index: doc.payload.chunk_index
  })) || []
};

return [{ json: conversationData }];
